#!/usr/bin/env bash
# stoa-identity compat smoke: qa-serve boots and serves with BOTH env prefixes.
# Round A: only legacy FDE2E_REPORT_* keys (+ legacy token keys) -> auth + login + CLI.
# Round B: fresh STOA_* keys as generated by init -> same assertions.
# Credential values are never printed. Every started process is reaped.
set -u
set +H

REPO="$(cd "$(dirname "$0")/../.." && pwd)"
CLI="${REPO}/src/cli/main.ts"
QA="${REPO}/scripts/qa/qa-serve.mjs"
BUN="$(command -v bun)"
FAIL=0
PASSED=0

ok()  { PASSED=$((PASSED+1)); echo "PASS ${1}"; }
bad() { FAIL=$((FAIL+1)); echo "FAIL ${1} ${2:-}"; }

stop_board() {
  "${BUN}" "${QA}" --stop --data-dir "${1}" --keep >/dev/null 2>&1 || true
}

run_round() {
  local label="${1}" D="${2}" AUTHKEY="${3}" url="" pid="" i=0
  local out="/tmp/stoa-smoke-${label}.out"
  : >"${out}"
  "${BUN}" "${QA}" --data-dir "${D}" --no-seed --keep >"${out}" 2>&1 &
  local qa_pid=$!
  while [ "${i}" -lt 100 ]; do
    url="$(grep -o '"url":"[^"]*"' "${out}" 2>/dev/null | head -1 | sed 's/"url":"//;s/"//')"
    [ -n "${url}" ] && break
    kill -0 "${qa_pid}" 2>/dev/null || break
    sleep 0.3
    i=$((i+1))
  done
  if [ -z "${url}" ]; then
    bad "${label} qa-serve start" "no url; tail: $(tail -2 "${out}" | tr '\n' ' ')"
    kill "${qa_pid}" 2>/dev/null || true
    stop_board "${D}"
    return
  fi
  pid="$(grep -o '"pid":[0-9]*' "${out}" | head -1 | cut -d: -f2)"
  echo "-- ${label} url=${url} serve_pid=${pid}"
  local health
  health="$(curl -sS --max-time 5 "${url}/healthz" || echo '{}')"
  case "${health}" in *'"ok":true'*) ok "${label} /healthz ok" ;; *) bad "${label} /healthz" "${health}" ;; esac
  local st mode
  st="$(curl -sS --max-time 5 "${url}/api/auth/status" || echo '{}')"
  mode="$(printf '%s' "${st}" | sed -n 's/.*"mode":"\([a-z]*\)".*/\1/p')"
  if [ "${mode}" = "auth" ]; then ok "${label} auth mode detected"; else bad "${label} auth mode" "${mode} <- ${st}"; fi
  local secret code body
  secret="$(sed -n "s/^${AUTHKEY}=//p" "${D}/.env" | head -1)"
  if [ -z "${secret}" ]; then
    bad "${label} read ${AUTHKEY}" "missing in ${D}/.env"
  else
    body="$(curl -sS --max-time 5 -X POST -H 'content-type: application/json' \
      --data "$(printf '{"secret":"%s"}' "${secret}")" "${url}/api/auth/login" || echo '{}')"
    case "${body}" in *'"token":"'*) ok "${label} login issues token via ${AUTHKEY}" ;; *) bad "${label} login" "${body:0:120}" ;; esac
  fi
  local who rc
  who="$("${BUN}" "${CLI}" who --data-dir "${D}" --env-files "${D}/.env,${D}/accounts/owner.env" --as owner 2>&1)"
  rc=$?
  if [ "${rc}" -eq 0 ]; then ok "${label} CLI who --as owner (token file lookup)"; else bad "${label} CLI who" "${who:0:160}"; fi
  stop_board "${D}"
  kill "${qa_pid}" 2>/dev/null || true
  wait "${qa_pid}" 2>/dev/null || true
  if [ -n "${pid}" ] && kill -0 "${pid}" 2>/dev/null; then
    bad "${label} serve reap" "pid ${pid} alive; sigkill"
    kill -9 "${pid}" 2>/dev/null || true
  else
    ok "${label} serve reaped (pid ${pid:-n/a})"
  fi
}

echo "== Round A: legacy FDE2E_REPORT_* keys =="
A="/tmp/report-qa-stoa-legacy-$$"
mkdir -p "${A}"
"${BUN}" "${CLI}" init --data-dir "${A}" --env-files "${A}/.env" >/dev/null 2>&1 || bad "legacy init" "init failed"
python3 - "${A}" <<'PY'
import sys, pathlib
d = pathlib.Path(sys.argv[1])
env = d/'.env'
t = env.read_text()
t = t.replace('STOA_AUTH=', 'FDE2E_REPORT_AUTH=').replace('STOA_SECRET=', 'FDE2E_REPORT_SECRET=')
env.write_text(t)
for acc in ('owner', 'manager'):
    p = d/'accounts'/f'{acc}.env'
    s = p.read_text().replace('STOA_ACCOUNT=', 'FDE2E_REPORT_ACCOUNT=').replace('STOA_TOKEN_', 'FDE2E_REPORT_TOKEN_')
    p.write_text(s)
print('round-A env keys:', [l.split('=')[0] for l in env.read_text().splitlines() if '=' in l and not l.startswith('#')])
PY
run_round legacy "${A}" "FDE2E_REPORT_AUTH"
echo "-- round A leftovers: $(pgrep -f "qa-serve.mjs --data-dir ${A}" | tr '\n' ' ')(none-if-empty)"

echo "== Round B: new STOA_* keys (init-generated) =="
B="/tmp/report-qa-stoa-new-$$"
mkdir -p "${B}"
"${BUN}" "${CLI}" init --data-dir "${B}" --env-files "${B}/.env" >/dev/null 2>&1 || bad "new init" "init failed"
grep -q '^STOA_AUTH=' "${B}/.env" && ok "init writes STOA_AUTH" || bad "init writes STOA_AUTH" ""
grep -q '^STOA_SECRET=' "${B}/.env" && ok "init writes STOA_SECRET" || bad "init writes STOA_SECRET" ""
grep -q '^STOA_TOKEN_OWNER=' "${B}/accounts/owner.env" && ok "init writes STOA_TOKEN_OWNER" || bad "init writes STOA_TOKEN_OWNER" ""
grep -q '^FDE2E_REPORT_TOKEN_OWNER=' "${B}/accounts/owner.env" && ok "new account file keeps legacy alias FDE2E_REPORT_TOKEN_OWNER (plugin compat)" || bad "legacy alias line" ""
run_round new "${B}" "STOA_AUTH"
echo "-- round B leftovers: $(pgrep -f "qa-serve.mjs --data-dir ${B}" | tr '\n' ' ')(none-if-empty)"
rm -rf "${A}" "${B}"

echo "== RESULT: PASS=${PASSED} FAIL=${FAIL} =="
[ "${FAIL}" -eq 0 ]
